    if (!NUMBERS[id]) { delete s.plan.numbers[id]; continue; }
    const np = s.plan.numbers[id];
    s.plan.numbers[id] = np.blocks || np.moves ? migrateNumber(np) : numberPlan(id);
  }
  s.plan.order = s.plan.order.filter((id) => NUMBERS[id] || ['accueil', 'entracte', 'final'].includes(id));
  for (const c of Object.keys(DEFAULT_HAIR)) if (!s.plan.hair[c] && c in s.plan.hair) s.plan.hair[c] = DEFAULT_HAIR[c];
  return s;
}

// the next season: new classes join, the dice change
function nextSeason(save) {
  const s = JSON.parse(JSON.stringify(save));
  s.season++; s.galaDone = false; s.seed = newSeed();
  addSeasonNumbers(s.plan, s.season);
  return s;
}

Object.assign(exports, { fresh, fromRound1, mend, nextSeason, newSeed });

// ---- the change itself: only a grown-up, only what the checker above lets through ----
if (Inputs.rows === undefined || Inputs.roles === undefined) return;
const refuse = (reason) => { Outputs.reason = reason; Outputs.refused(); };
if (!(Inputs.roles || []).includes('grownup')) return refuse('notGrownup');
let fields = Inputs.fields;
if (typeof fields === 'string') { try { fields = JSON.parse(fields); } catch (e) { fields = null; } }
if (!fields || typeof fields !== 'object' || Array.isArray(fields)) return refuse('badFields');
const table = String(Inputs.table || '');
if (!TABLES[table]) return refuse('badTable');
const rowId = TABLES[table].one ? 'row' : String(Inputs.rowId || '');
const get = (o, k) => (o && typeof o.get === 'function' ? o.get(k) : o && o[k]);
const old = (Inputs.rows || []).find((r) => get(r, 'table') === table && get(r, 'rowId') === rowId);
let before = {};
if (old) { try { before = JSON.parse(get(old, 'fields')) || {}; } catch (e) { before = {}; } }
const result = checkChange(table, rowId, { ...before, ...fields });
if (!result.ok) return refuse(result.reason);
Outputs.table = table;
Outputs.rowId = rowId;
Outputs.fieldsJson = JSON.stringify(result.fields);
Outputs.existingId = old ? get(old, 'id') || old.id : '';
if (old) Outputs.update(); else Outputs.create();

content.content:
// One press → what changes. Every button in the game sends an event on the channel "gala-act" with an `act` (what
// kind of press: "order:up", "tab", "go") and an `arg` (which card, which tab…). The Game page's dispatcher Function
// hands both here with the save, the screen state and the 3D stage, and writes back what this returns:
//   { save, ui, toast } — a new save, a patch for the screen state, a sentence for the toast.
// The 3D stage is told directly (begin a run, turn the camera): it is the one thing here that is not state.
const A = use('game/actions');
const S = use('game/save');
const { simulate } = use('rules/engine');
const { NUMBERS, seasonRules } = use('rules/data');
const { sayText } = use('view/run');

const UI0 = { screen: 'prep', tab: 'order', pickNum: 'G1', selBlock: {}, selMove: null, selChain: null, allMoves: false, editB: false, pickDancer: null, armed: null, selected: null, pickedRoom: null, shopCat: 'hall', speed: 1, follow: true, introForced: false, confirm: null, renaming: false };
const num = (x) => Number(x);
const split = (s) => { const i = String(s).indexOf(':'); return i < 0 ? [String(s), ''] : [String(s).slice(0, i), String(s).slice(i + 1)]; };

function tabChange(save, ui, k) {
  const patch = { tab: k, armed: null, confirm: null, renaming: false };
  if (k !== 'build') patch.selected = null;
  if (k === 'build') patch.pickedRoom = 'dr';
  else if (['formation', 'costumes', 'parking'].includes(k) || ui.pickedRoom === 'dr') patch.pickedRoom = null;
  return { ui: patch };
}

function begin(save, ui, stage, mode, tryId) {
  if (!stage || (mode === 'gala' && save.galaDone)) return {};
  const res = stage.beginRun(mode, tryId);
  if (!res) return {};
  return { ui: { screen: 'run', res, live: { mode, t: 0, done: false, feed: [], tryId: tryId || null }, speed: 1, pickedRoom: null, armed: null, selected: null, confirm: null } };
}
function stop(stage) {
  if (stage) stage.stopRun();
  return { ui: { screen: 'prep', res: null, live: null } };
}

function dispatch(act, arg, save, ui, w, stage) {
  ui = { ...UI0, ...(ui || {}) };
  const [group, what] = split(act);
  const out = (r) => r || {};
  switch (group) {
    case 'tab': return tabChange(save, ui, String(arg));
    case 'lang': return { save: { ...save, lang: save.lang === 'en' ? 'fr' : 'en' } };
    case 'sound': { const on = save.sound === false; if (on && stage) stage.wake(); return { save: { ...save, sound: on } }; }
    case 'intro': return { ui: { introForced: true } };
    case 'introGo': {
      const r = { save: { ...save, seenIntro: save.season }, ui: { introForced: false } };
      if (save.season === 2) Object.assign(r.ui, tabChange(save, ui, 'parking').ui);
      return r;
    }
    case 'cam': if (stage) stage.camCmd(String(arg)); return {};
    case 'go': {
      const id = String(arg);
      if (id === 'rehearse') return begin(save, ui, stage, 'rehearsal');
      if (id === 'gala') return begin(save, ui, stage, 'gala');
      if (id === 'speed') { const s = ui.speed >= 8 ? 1 : ui.speed * 2; if (stage) stage.setSpeed(s); return { ui: { speed: s } }; }
      if (id === 'follow') { const f = !ui.follow; if (stage) stage.setFollow(f); return { ui: { follow: f } }; }
      if (id === 'skipNum') { if (stage) stage.skipNumber(); return {}; }
      if (id === 'skip') { if (stage) stage.skipToEnd(); return {}; }
      if (id === 'stop' || id === 'back') return stop(stage);
      if (id === 'nextSeason') { stop(stage); return { save: S.nextSeason(save), ui: { ...UI0, screen: 'prep', res: null, live: null } }; }
      return {};
    }
    case 'try': return begin(save, ui, stage, 'try', ui.pickNum && NUMBERS[ui.pickNum] ? ui.pickNum : 'G1');
    // the 3D stage reports
    case 'runDone': {
      const live = arg || ui.live || {};
      const r = { ui: { screen: 'results', live } };
      if (live.mode === 'gala' && ui.res && !save.galaDone) r.save = A.finishGala(save, ui.res).save;
      return r;
    }
    case 'say': return Array.isArray(arg) ? { toast: sayText(arg, w) } : {};
    case 'stageUi': return { ui: arg && typeof arg === 'object' ? arg : {} };
    case 'place': return out(A.build(save, ui, 'place', arg, w));
    case 'key': return out(A.build(save, ui, String(arg), null, w));
    // the tabs
    case 'order': {
      if (what === 'up' || what === 'down') return out(A.moveCard(save, String(arg), what === 'up' ? -1 : 1));
      const [which, d] = split(what); return out(A.orderStep(save, which, num(d)));
    }
    case 'form': {
      if (what === 'renameAsk') return { ui: { renaming: true } };
      if (what === 'renameCancel') return { ui: { renaming: false } };
      if (what === 'delAsk') return { ui: { confirm: 'delBlock' } };
      if (what === 'confirmNo') return { ui: { confirm: null } };
      if (what === 'renameBlock') { const r = out(A.formationAct(save, ui, 'renameBlock', arg, w)); if (r.save) r.ui = { renaming: false }; return r; }
      if (what === 'delBlock') { const r = out(A.formationAct(save, ui, 'delBlock', null, w)); r.ui = { ...(r.ui || {}), confirm: null }; return r; }
      const idx = (prefix) => num(String(arg).split(prefix).pop());
      if (what === 'step') return out(A.formationAct(save, ui, 'step', idx('s'), w));
      if (what === 'chain') return out(A.formationAct(save, ui, 'chain', idx('c'), w));
      if (what === 'pickDancer') return out(A.formationAct(save, ui, 'pickDancer', idx('-'), w));
      if (what === 'stepTool' || what === 'chainTool') return out(A.formationAct(save, ui, what, arg === 'x' ? 'x' : num(arg), w));
      if (what === 'dropDancer') return out(A.formationAct(save, ui, 'dropDancer', { ...arg, index: num(String(arg.id).split('-').pop()) }, w));
      return out(A.formationAct(save, ui, what, arg, w));
    }
    case 'gouter': {
      if (what === 'snack') return out(A.snack(save, String(arg), w));
      const [which, d] = split(what); return out(A.gouterStep(save, which, num(d)));
    }
    case 'cos': return out(A.costume(save, ui, what, String(arg), w));
    case 'build': {
      if (what === 'goLoge') return { ui: { pickedRoom: 'dr' } };
      return out(A.build(save, ui, what, arg, w));
    }
    case 'park': return out(A.parking(save, what, arg, w));
    case 'shop': {
      if (what === 'cat') return { ui: { shopCat: String(arg) } };
      return out(A.shop(save, what, String(arg), w));
    }
    case 'note': {
      if (what === 'resetAsk') return { ui: { confirm: 'reset' } };
      if (what === 'resetNo') return { ui: { confirm: null } };
      if (what === 'resetYes') { stop(stage); return { save: S.fresh(save.lang), ui: { ...UI0 } }; }
      return {};
    }
    default: return {};
  }
}

// what the stage's sync needs to know is worth a re-sync: anything but the live evening
const syncKey = (save, ui) => JSON.stringify([save, ui && { ...ui, res: null, live: null }]);

Object.assign(exports, { dispatch, UI0, syncKey, seasonRulesOf: seasonRules, simulate });
// What a press does to the save: the onclick handlers of reference/src/ui.js, as pure functions. Each takes the save
// and the screen state and returns { save, ui, toast } — only the parts that changed. The graph writes them back
// into the Global Stores; nothing here touches the page.
const { RULES, NUMBERS, MOVES, MAX_MOVES, OUTFITS, HAIRS, SHOES, ACCS, PIECES, LOGE, SNACKS, UPGRADES } = use('rules/data');
const { clamp, isOwned, fits, footprint, routineInfo, danceOf, stageOf } = use('rules/engine');
const { pickedNum } = use('view/common');
const { geometry } = use('view/formation');
const { foodPrice } = use('view/prep');
const { cleanName } = use('settings/check');

const copy = (o) => JSON.parse(JSON.stringify(o));
const MAX_BLOCKS = 8, MAX_CHAIN = 60;

// buying: a price in stars, kept for good
function buy(save, kind, id, w) {
  const price = kind === 'up' ? UPGRADES[id].price : kind === 'food' ? foodPrice(id) : (({ outfit: OUTFITS, hair: HAIRS, shoes: SHOES, acc: ACCS, piece: PIECES, snack: SNACKS })[kind][id].price || 0);
  const name = kind === 'up' ? w.nm(UPGRADES[id]) : kind === 'food' ? w(`foods_${id}`) : w.nm(({ outfit: OUTFITS, hair: HAIRS, shoes: SHOES, acc: ACCS, piece: PIECES, snack: SNACKS })[kind][id]);
  const sc = save.school;
  if (sc.stars < price) return { ok: false, toast: w('notEnough') };
  sc.stars -= price;
  if (kind === 'up') sc.upgrades[id] = id === 'sieges' ? (sc.upgrades[id] || 0) + 1 : true;
  else sc.owned[`${kind}:${id}`] = true;
  if (kind === 'up' && id === 'logeXL') sc.logeCols = LOGE.colsBig;
  if (kind === 'up' && id.startsWith('decor')) save.plan.backdrop = { decorForet: 'foret', decorMer: 'mer', decorVille: 'ville' }[id];
  return { ok: true, toast: w('bought', name) };
}

/* ---------------- the programme ---------------- */
function orderStep(save0, which, d) {
  const save = copy(save0), P = save.plan;
  if (which === 'start') P.start = clamp(P.start + d * 300, RULES.startMin, RULES.startMax);
  if (which === 'interval') P.interval = clamp(P.interval + d * 300, RULES.intervalMin, RULES.intervalMax);
  return { save };
}
function moveCard(save0, id, d) {
  const save = copy(save0), o = save.plan.order, i = o.indexOf(id), j = clamp(i + d, 1, o.length - 2);
  if (i < 1 || i === j) return {};
  o.splice(i, 1); o.splice(j, 0, id);
  return { save };
}

/* ---------------- the formation and the choreography ---------------- */
function formationAct(save0, ui0, act, arg, w) {
  const save = copy(save0), ui = copy(ui0), id = pickedNum(save, ui, 'G1'), N = NUMBERS[id], np = save.plan.numbers[id];
  ui.selBlock = ui.selBlock || {};
  const bid = np.blocks.some((b) => b.id === ui.selBlock[id]) ? ui.selBlock[id] : np.blocks[0].id, blk = np.blocks.find((b) => b.id === bid);
  const free = () => 'abcdefgh'.split('').find((c) => !np.blocks.some((b) => b.id === c));
  const moveIn = (list, k, d) => { const j = clamp(k + d, 0, list.length - 1); if (j !== k) { const [x] = list.splice(k, 1); list.splice(j, 0, x); } return j; };
  switch (act) {
    case 'pickNum': return { ui: { ...ui0, pickNum: arg, pickDancer: null, editB: false, selMove: null, selChain: null } };
    case 'ab': {
      if (arg === 'B' && !np.B) np.B = np.A.map((p) => ({ ...p }));
      return { save, ui: { ...ui0, editB: arg === 'B' } };
    }
    case 'block': return { ui: { ...ui, selBlock: { ...ui.selBlock, [id]: arg }, selMove: null } };
    case 'newBlock': case 'copyBlock': {
      if (np.blocks.length >= MAX_BLOCKS) return { toast: w('maxBlocks') };
      const f = free();
      np.blocks.push(act === 'newBlock' ? { id: f, name: f.toUpperCase(), moves: [] } : { id: f, name: `${blk.name} 2`.slice(0, 24), moves: [...blk.moves] });
      return { save, ui: { ...ui, selBlock: { ...ui.selBlock, [id]: f }, selMove: null } };
    }
    case 'renameBlock': {
      const name = cleanName(arg, 24);
      if (!name) return { toast: w('nameRefused') };
      blk.name = name; return { save };
    }
    case 'delBlock': {
      if (np.blocks.length < 2) return {};
      np.blocks = np.blocks.filter((b) => b !== blk); np.chain = np.chain.filter((x) => x !== bid);
      return { save, ui: { ...ui, selChain: null, selMove: null } };
    }
    case 'step': return { ui: { ...ui0, selMove: ui0.selMove === arg ? null : arg } };
    case 'stepTool': {
      const k = ui.selMove; if (k === null || k === undefined || !blk.moves[k]) return {};
      if (arg === 'x') { blk.moves.splice(k, 1); return { save, ui: { ...ui0, selMove: null } }; }
      return { save, ui: { ...ui0, selMove: moveIn(blk.moves, k, arg) } };
    }
    case 'addMove': {
      if (!MOVES[arg]) return {};
      if (blk.moves.length >= MAX_MOVES) return { toast: w('maxMoves') };
      blk.moves.push(arg);
      if (MOVES[arg].swap && !np.B) np.B = np.A.map((p) => ({ ...p }));
      return { save };
    }
    case 'chain': return { ui: { ...ui0, selChain: ui0.selChain === arg ? null : arg } };
    case 'chainTool': {
      const k = ui.selChain; if (k === null || k === undefined || k >= np.chain.length) return {};
      if (arg === 'x') { np.chain.splice(k, 1); return { save, ui: { ...ui0, selChain: null } }; }
      return { save, ui: { ...ui0, selChain: moveIn(np.chain, k, arg) } };
    }
    case 'addChain': {
      if (np.chain.length >= MAX_CHAIN) return { toast: w('maxChain') };
      np.chain.push(bid); return { save };
    }
    case 'filter': return { ui: { ...ui0, allMoves: arg === 'all' } };
    case 'pickDancer': return { ui: { ...ui0, pickDancer: arg } };
    case 'dropDancer': {
      // arg: { index, left, top } — the dot's new top-left corner on the plan, in pixels
      const g = geometry(stageOf(save.school)), info = routineInfo(danceOf(np).moves, N.style, false);
      const F = ui.editB && info.swaps && np.B ? np.B : np.A, size = 0.6 * g.k;
      const x = (arg.left + size / 2) / g.k - g.W - 0.9, z = g.D + 0.5 - (arg.top + size / 2) / g.k;
      if (!F[arg.index]) return {};
      F[arg.index] = { x: clamp(Math.round(x * 2) / 2, -g.W - 0.5, g.W + 0.5), z: clamp(Math.round(z * 2) / 2, 0, g.D) };
      return { save, ui: { ...ui0, pickDancer: arg.index } };
    }
    default: return {};
  }
}

/* ---------------- the goûter ---------------- */
function gouterStep(save0, which, d) {
  const save = copy(save0), P = save.plan;
  if (which === 'cake') P.cakeG = clamp(P.cakeG + d * 50, 0, 8000);
  if (which === 'bottles') P.bottles = clamp(P.bottles + d, 0, 20);
  if (which === 'crepes') P.crepes = clamp((P.crepes || 0) + d, 0, 60);
  if (which === 'compotes') P.compotes = clamp((P.compotes || 0) + d, 0, 60);
  return { save };
}
function snack(save0, id, w) {
  if (!SNACKS[id]) return {};
  const save = copy(save0);
  if (!isOwned(save.school, 'snack', id)) { const b = buy(save, 'snack', id, w); if (!b.ok) return { toast: b.toast }; save.plan.snack = id; return { save, toast: b.toast }; }
  save.plan.snack = id; return { save };
}

/* ---------------- the costumes ---------------- */
function costume(save0, ui, act, arg, w) {
  const save = copy(save0), id = pickedNum(save, ui), cos = save.plan.numbers[id].costume;
  if (act === 'pickNum') return { ui: { ...ui, pickNum: arg } };
  if (act === 'color') { cos.color = arg; return { save }; }
  let toast;
  if (act === 'item') {
    const [kind, k] = String(arg).split(':'), list = { outfit: OUTFITS, shoes: SHOES, acc: ACCS }[kind];
    if (!list || !list[k]) return {};
    if (!isOwned(save.school, kind, k)) { const b = buy(save, kind, k, w); if (!b.ok) return { toast: b.toast }; toast = b.toast; }
    cos[kind === 'outfit' ? 'outfit' : kind === 'shoes' ? 'shoes' : 'acc'] = k;
    return { save, toast };
  }
  if (act === 'hair') {
    const [cls, k] = String(arg).split(':');
    if (!HAIRS[k]) return {};
    if (!isOwned(save.school, 'hair', k)) { const b = buy(save, 'hair', k, w); if (!b.ok) return { toast: b.toast }; toast = b.toast; }
    save.plan.hair[cls] = k;
    return { save, toast };
  }
  return {};
}

/* ---------------- the dressing room ---------------- */
function build(save0, ui0, act, arg, w) {
  const save = copy(save0), ui = copy(ui0), sc = save.school, cols = sc.logeCols;
  const same = (a, b) => a && b && a.id === b.id && a.c === b.c && a.r === b.r && a.rot === b.rot;
  const selIndex = ui.selected ? sc.furniture.findIndex((f) => same(f, ui.selected)) : -1;
  switch (act) {
    case 'name': {
      const name = cleanName(arg, 40);
      if (name === null) return { toast: w('nameRefused') };
      sc.name = name; return { save };
    }
    case 'piece': {
      if (!PIECES[arg]) return {};
      let toast;
      if (!isOwned(sc, 'piece', arg)) { const b = buy(save, 'piece', arg, w); if (!b.ok) return { toast: b.toast }; toast = b.toast; }
      return { save, toast, ui: { ...ui0, armed: ui0.armed && ui0.armed.id === arg ? null : { id: arg, rot: 0 }, selected: null } };
    }
    case 'rotateArmed': return ui.armed ? { ui: { ...ui0, armed: { ...ui.armed, rot: (ui.armed.rot + 1) % 4 } } } : {};
    case 'cancelArmed': {
      if (ui.armed && ui.armed.was) sc.furniture.push(ui.armed.was);
      return { save, ui: { ...ui0, armed: null } };
    }
    case 'rotateSelected': {
      if (selIndex < 0) return {};
      const f = sc.furniture[selIndex], old = { c: f.c, r: f.r, rot: f.rot };
      f.rot = (f.rot + 1) % 4;
      if (!fits(f, sc.furniture, cols, f)) { const fp = footprint(f); f.c = clamp(f.c, 0, cols - fp.w); f.r = clamp(f.r, 0, LOGE.rows - fp.d); if (!fits(f, sc.furniture, cols, f)) Object.assign(f, old); }
      return { save, ui: { ...ui0, selected: { ...f } } };
    }
    case 'moveSelected': {
      if (selIndex < 0) return {};
      const [f] = sc.furniture.splice(selIndex, 1);
      return { save, ui: { ...ui0, armed: { id: f.id, rot: f.rot, was: f }, selected: null } };
    }
    case 'removeSelected': {
      if (selIndex < 0) return {};
      sc.furniture.splice(selIndex, 1);
      return { save, ui: { ...ui0, selected: null } };
    }
    case 'place': {
      // arg: { id, c, r, rot } — the 3D view says where the ghost stood when she tapped
      if (!ui.armed || !PIECES[arg.id] || !fits(arg, sc.furniture, cols)) return {};
      const f = { id: arg.id, c: arg.c, r: arg.r, rot: arg.rot };
      sc.furniture.push(f);
      return { save, ui: { ...ui0, selected: { ...f }, armed: ui.armed.was ? null : ui.armed } };
    }
    case 'select': return { ui: { ...ui0, selected: arg ? { ...arg } : null } };
    default: return {};
  }
}

/* ---------------- the car park and the shop ---------------- */
function parking(save0, act, arg, w) {
  const save = copy(save0), P = save.plan;
  if (act === 'width') P.parking.width = Number(arg);
  if (act === 'doors') P.parking.doors = Number(arg);
  if (act === 'up') { if (save.school.upgrades[arg] || !UPGRADES[arg]) return {}; const b = buy(save, 'up', arg, w); return b.ok ? { save, toast: b.toast } : { toast: b.toast }; }
  return { save };
}
function shop(save0, act, arg, w) {
  const save = copy(save0);
  if (act === 'backdrop') { save.plan.backdrop = arg; return { save }; }
  if (act === 'buy') {
    const [kind, id] = String(arg).split('|');
    const b = buy(save, kind, id, w);
    return b.ok ? { save, toast: b.toast } : { toast: b.toast };
  }
  return {};
}

/* ---------------- the end of a gala ---------------- */
function finishGala(save0, R) {
  const save = copy(save0);
  save.galaDone = true; save.school.stars += R.points; save.school.earned += R.points;
  save.notebook.unshift({ season: save.season, at: new Date().toISOString().slice(0, 10), points: R.points, satisfaction: R.parents.satisfaction, nums: Object.fromEntries(Object.values(R.perf).map((p) => [p.id, p.total])) });
  return { save };
}

Object.assign(exports, { buy, orderStep, moveCard, formationAct, gouterStep, snack, costume, build, parking, shop, finishGala });
// Words for the screen. The words themselves are rows in the App's "Words" Static Data node ({ key, fr, en });
// this file only fills a row's template: {0} {1}… are the arguments, {0:s} is "s" when argument 0 is more than 1,
// {0:lower} lower-cases it. It also formats clock times, durations and numbers the way reference/src/i18n.js did.
const { CLS, NUMBERS, NAMES, MOVES } = use('rules/data');

// rows → { key: text } for one language
function dictionary(rows, lang) {
  const d = {};
  for (const r of rows || []) d[r.key] = r[lang] || r.fr;
  return d;
}

function fill(template, args) {
  return String(template).replace(/\{(\d)(?::(s|lower))?\}/g, (_, i, how) => {
    const v = args[+i];
    if (how === 's') return Number(v) > 1 ? 's' : '';
    if (how === 'lower') return String(v ?? '').toLowerCase();
    return v === undefined || v === null ? '' : String(v);
  });
}

