import json,sys,os
base=sys.argv[1]
for comp in sys.argv[2:]:
    p=os.path.join(base,comp)
    print("=====",comp)
    try: print("DESC:", json.load(open(p+'/component.json')).get('description',''))
    except Exception as e: pass
    n=json.load(open(p+'/nodes.json'))
    def walk(nodes,depth=0):
        for x in nodes:
            params=x.get('parameters',{})
            ps={}
            for k,v in params.items():
                s=json.dumps(v) if not isinstance(v,str) else v
                ps[k]=s if len(s)<=int(os.environ.get('W','160')) else s[:int(os.environ.get('W','160'))]+'…'
            print('  '*depth+f"- {x.get('id')} [{x.get('type')}] {x.get('label','')} {json.dumps(ps,ensure_ascii=False)}")
            for k in ('children',):
                if x.get(k): walk(x[k],depth+1)
    walk(n.get('nodes',[]))
    for k,v in n.items():
        if k not in ('nodes','$schema','componentId','version'): print("EXTRA",k,json.dumps(v)[:500])
    try:
        c=json.load(open(p+'/connections.json'))
        for e in c.get('connections',c if isinstance(c,list) else []):
            print("   ~", e.get('from', e.get('fromId')), e.get('fromPort'), '->', e.get('to',e.get('toId')), e.get('toPort'))
    except Exception as e: print("conn err",e)
EOF
