===== Pages/Game The game: the 3D school fills the window; over it the top bar, the camera bar, the side sheet (the preparations, the live evening, the verdicts), the toast and the season's letter. Drawn once the start-up has opened the save.
- gm_page [Page]  children= ['gm_root'] {"title": "Le Gala de danse", "urlPath": "game"}
- gm_root [Group] The window children= ['gm_stage', 'gm_top', 'gm_cam', 'gm_sheet', 'gm_float', 'gm_toast', 'gm_letter'] {"position": "relative", "width": {"value": 100, "unit": "vw"}, "height": {"value": 100, "unit": "vh"}, "clip": true, "backgroundColor": "var(--background)", "mounted": false}
- gm_stage [/Game/Stage 3D]  children=  {}
- gm_top [/Game/Top Bar]  children=  {}
- gm_ready [Variable2] ready children=  {"name": "ready"}
- gm_save [net.noodl.GlobalStore.Subscribe]  children=  {"storeName": "gala", "keys": "save"}
- gm_ui [net.noodl.GlobalStore.Subscribe]  children=  {"storeName": "ui", "keys": "ui"}
- gm_words [Variable2] words (shared on purpose) children=  {"name": "words"}
- gm_dispatch [/Game/Dispatcher]  children=  {}
- gm_cam [/Game/Camera Bar]  children=  {}
- gm_sheet [/Game/Sheet]  children=  {}
- gm_float [/Game/Furniture Toolbar]  children=  {}
