// Writes the grown-ups' checker (tools/check.src.js) into the app twice: as the script file the browser uses
// (app/scripts/settings/check.js) and as the body pasted into the cloud function (tools/check.cloud.js), with the
// ids the game knows filled in from gala-rules/src/data.js.  Run: node tools/sync-check.mjs
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const D = await import(pathToFileURL(join(root, 'gala-rules/src/data.js')));
const EXTRA_ICONS = ['💃', '🕺', '🩰', '🎀', '👑', '🌸', '🌼', '🌙', '⭐', '🌟', '✨', '💫', '🦋', '🐝', '🐞', '🦄', '🐬', '🐧', '🦊', '🐼', '🐸', '🌈', '☀️', '❄️', '🔥', '🍀', '🎈', '🎉', '🎵', '🎶', '🥁', '🎻', '🎺', '🪄', '🧚', '🧜', '🦢', '🕊️', '🌊', '🌀', '🔄', '⬆️', '⬇️', '➡️', '⬅️', '👏', '🙌', '🤸', '🧘', '🦵', '👣', '💎', '🪩', '🧢', '👗', '👘', '🥻', '🩱', '👒', '🎩'];
const icons = new Set(EXTRA_ICONS);
for (const t of [D.MOVES, D.OUTFITS, D.PIECES, D.SNACKS, D.UPGRADES]) for (const r of Object.values(t)) if (r.icon) icons.add(r.icon);
const KNOWN = {
  moves: Object.keys(D.MOVES), outfits: Object.keys(D.OUTFITS), hairs: Object.keys(D.HAIRS), shoes: Object.keys(D.SHOES), accs: Object.keys(D.ACCS),
  pieces: Object.keys(D.PIECES), snacks: Object.keys(D.SNACKS), upgrades: Object.keys(D.UPGRADES), numbers: Object.keys(D.NUMBERS),
  icons: [...icons], styles: Object.keys(D.STYLES), themes: [...new Set(Object.values(D.NUMBERS).map((n) => n.theme))],
};
const src = readFileSync(join(root, 'tools/check.src.js'), 'utf8').replace('__KNOWN__', JSON.stringify(KNOWN));
const head = '// GENERATED from tools/check.src.js by tools/sync-check.mjs — edit that file and run it again.\n';
mkdirSync(join(root, 'app/scripts/settings'), { recursive: true });
writeFileSync(join(root, 'app/scripts/settings/check.js'), head + src + '\nObject.assign(exports, { TABLES, KNOWN, cleanName, rude, checkChange, toRows });\n');
writeFileSync(join(root, 'tools/check.cloud.js'), head + src);
console.log(`checker written: ${KNOWN.icons.length} icons, ${KNOWN.themes.length} themes`);
// Copies gala-rules/src into the NodeGX project's script files, unchanged except for the module lines:
// NodeGX script files are CommonJS-style (`exports`, `use('rules/data')`), gala-rules is ES modules.
// Run it again whenever gala-rules changes:  node tools/sync-rules.mjs
// Then check the copy plays the same game as the original:  node tools/check-rules.mjs
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const src = join(root, 'gala-rules/src'), out = join(root, 'app/scripts/rules');
mkdirSync(out, { recursive: true });

for (const name of ['data', 'plan', 'engine', 'tunes']) {
  let code = readFileSync(join(src, `${name}.js`), 'utf8');
  const names = [];
  code = code.replace(/^import\s*\{([^}]*)\}\s*from\s*'\.\/(\w+)\.js';/gm, (_, list, file) => `const {${list}} = use('rules/${file}');`);
  code = code.replace(/^export (const|let|function) (\w+)/gm, (_, kind, id) => { names.push(id); return `${kind} ${id}`; });
  if (/^\s*(import|export)\b/m.test(code)) throw new Error(`${name}.js: a module line this copier does not know`);
  const head = `// GENERATED from gala-rules/src/${name}.js by tools/sync-rules.mjs — do not edit here, edit gala-rules and run it again.\n`;
  writeFileSync(join(out, `${name}.js`), `${head}${code}\nObject.assign(exports, { ${names.join(', ')} });\n`);
  console.log(`scripts/rules/${name}.js: ${names.length} exports`);
}
// Copies the 3D and music modules of reference/src (world.js, people.js, play.js, music.js) into the app's script
// files as factories. A NodeGX script file has no window, no document and no `import`, so each module becomes
// `exports.create(env)`: the "3D stage" Function hands it three.js, the window and the shared state object `G`.
// The code itself is the reference's, with these mechanical changes only:
//   - import lines → `use('rules/…')` for the rules, `env.mods.<file>` for each other, `env.T` for three.js;
//   - `document.createElement('canvas')` (textures drawn off-screen) → `new OffscreenCanvas(1, 1)`, never on the page;
//   - the renderer makes its own canvas (the Function puts it in the 3D Group) instead of finding #gl;
//   - innerWidth / innerHeight → the 3D Group's size (env.size).
// Run: node tools/sync-stage.mjs
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const out = join(root, 'app/scripts/stage');
mkdirSync(out, { recursive: true });
const RULES = { data: 'rules/data', engine: 'rules/engine', tunes: 'rules/tunes' };

function convert(name) {
  let code = readFileSync(join(root, 'reference/src', `${name}.js`), 'utf8');
  const names = [];
  code = code.replace(/^import \* as T from 'three';/m, 'const T = env.T;');
  code = code.replace(/^import\s*\{([^}]*)\}\s*from\s*'\.\/(\w+)\.js';/gm, (_, list, file) => {
    if (file === 'state.js' || file === 'state') return `const {${list}} = env;`;
    if (RULES[file]) return `const {${list}} = use('${RULES[file]}');`;
    return `const {${list}} = env.mods.${file};`;
  });
  code = code.replace(/^export \{([^}]*)\};?$/gm, (_, list) => { names.push(...list.split(',').map((s) => s.trim()).filter(Boolean)); return ''; });
  code = code.replace(/^export (async function|function|const|let|class) (\w+)/gm, (_, kind, id) => { names.push(id); return `${kind} ${id}`; });
  if (name === 'world') {
    const before = code;
    code = code.replace("const canvas = document.getElementById('gl');\nconst renderer = new T.WebGLRenderer({ canvas, antialias",
      "const renderer = new T.WebGLRenderer({ antialias");
    if (code === before) throw new Error('world.js: the canvas lines moved');
    code = code.replace(/^(renderer\.setPixelRatio)/m, 'const canvas = renderer.domElement;\n$1');
  }
  code = code.replace(/document\.createElement\('canvas'\)/g, 'new OffscreenCanvas(1, 1)');
  code = code.replace(/\binnerWidth\b/g, 'SIZE.w').replace(/\binnerHeight\b/g, 'SIZE.h');
  code = code.replace(/new OfflineAudioContext/g, 'new window.OfflineAudioContext');
  if (/^\s*(import|export)\b/m.test(code) || /document\.getElementById/.test(code)) throw new Error(`${name}.js: a line this copier does not know`);
